Definition free_s (Σ : rtsA) (k : nat) (s : secst) (D' : depot) : rtsA :=
  mkRtsA (lay Σ) (pr Σ) (ca Σ) (ca_init Σ) (upd (sec Σ) k (mkSec (s_mb s) (s_n s) true)) (sec_nres Σ)
